    if (enemy.hp < enemy.maxHp) {
      ctx.shadowBlur = 0; ctx.fillStyle = '#34233b'; ctx.fillRect(-35, -58, 70, 4);
      ctx.fillStyle = '#ff758e'; ctx.fillRect(-35, -58, 70 * Math.max(0, enemy.hp / enemy.maxHp), 4);
