export function makeRng(seed) {
  let state = (Number(seed) >>> 0) || 1;
  return {
    next() { state = (state + 0x6d2b79f5) | 0; let value = state; value = Math.imul(value ^ (value >>> 15), value | 1); value ^= value + Math.imul(value ^ (value >>> 7), value | 61); return ((value ^ (value >>> 14)) >>> 0) / 4294967296; },
    range(min, max) { return min + this.next() * (max - min); },
    pick(items) { return items[Math.floor(this.next() * items.length)]; },
  };
}
